/* AS Roma DNA — imperial garnet night, giallorossi gold */
.theme-roma {
  --bg: oklch(0.190 0.048 9.6);
  --surface: oklch(0.232 0.057 12.1);
  --surface-2: oklch(0.272 0.069 11.7);
  --fg: oklch(0.946 0.029 82.6);
  --fg-muted: oklch(0.703 0.041 60.7);
  --accent: oklch(0.827 0.170 83.1);
  --accent-fg: oklch(0.190 0.048 9.6);
  --accent-2: oklch(0.437 0.169 17.9);
  --line: oklch(0.72 0.12 80 / 30%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.827 0.170 83.1);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Forum", serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.18em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-roma h1,
.theme-roma h2,
.theme-roma h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-roma { --font-ui: var(--font-display); }
.theme-roma h1, .theme-roma h2 { text-transform: uppercase; }
.theme-roma button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-roma h1 { letter-spacing: 0.06em; }
.theme-roma h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.7rem; border-block: 1px solid var(--accent); }
.theme-roma h2::before { content: "SPQR "; font-size: 0.5em; color: var(--accent); letter-spacing: 0.3em; vertical-align: middle; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
